// Memory Hierarchy Levels (Typical Latency, Cost, Size)

// L1 Cache: <1ns, Highest, KB range, On-chip
int L1_Access_Time_Cycles = 1;

// L2 Cache: ~10ns, High, MB range, On-chip/Near-chip
int L2_Access_Time_Cycles = 10;

// L3 Cache: ~50ns, Moderate, MB/GB range, Shared Die
int L3_Access_Time_Cycles = 50;

// Main Memory (DRAM): ~100ns, Low, GB range, Off-chip
int DRAM_Access_Time_Cycles = 100;

// Cache Locality Principles

// Temporal Locality: Re-using data/instructions soon.
// Loop body variables are often temporally local.
int sum = 0;
for (int i=0; i<N; ++i) { sum += i; }

// Spatial Locality: Accessing nearby data/instructions.
// Array iteration is often spatially local.
int array[100];
for (int i=0; i<100; ++i) { array[i] = i; } // Sequential access
